contract InvMutTest {
    C c;

    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(address _target, bytes memory _data) public payable {
        uint256 beforeBalance = address(c).balance;
        uint256 beforeCount = c.depositsCount(); if (__ESBMC_reverted()) return;

        c.sendMoney(_target, 0, _data); if (__ESBMC_reverted()) return;

        uint256 afterBalance = address(c).balance;
        uint256 afterCount = c.depositsCount(); if (__ESBMC_reverted()) return;

        assert(afterBalance == beforeBalance && afterCount == beforeCount);
    }

    receive() external payable {}
}

